public sealed class SqlMilestoneReviewFixTests
{
    private static async Task Permit(IServiceProvider services, CoreScope owner, Guid universe, Guid work, Guid edition, bool ai)
    { var sources = services.GetRequiredService<ISourceRegistry>(); var permission = await sources.PermissionAsync(owner, universe, edition, new(Guid.NewGuid(), "fixture:owned-original-review-regression", ["en-IN"], ["IN"], ["Image", "Text"], false, true, true, ai, true, "Original synthetic test fixture only."), default); var detail = await sources.InspectAsync(owner, universe, work, default); await sources.ReviewPermissionAsync(owner, universe, permission, new(detail.Permissions.Single(x => x.Id == permission).RowVersion, "Approved"), default); }
    [SqlFact]
    public async Task Media_generation_checks_direct_inherited_dispatch_and_acceptance_ai_rights()
    {
        using var root = WatchTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await RegistryTestFixture.Setup(s, "review-generation-rights"); var c = await RegistryTestFixture.Character(s, f, "rights-guest"); var source = s.GetRequiredService<ISourceRegistry>(); var media = s.GetRequiredService<IMediaLibrary>(); var work = await source.RegisterAsync(f.Owner, f.Universe, new(Guid.NewGuid(), "no-ai", "Original synthetic reference", "Synthetic"), default); var edition = await source.EditionAsync(f.Owner, f.Universe, work, new(Guid.NewGuid(), "v1", "Fixture author", null, "Owned fixture", "en-IN", "fixture:original"), default); await Permit(s, f.Owner, f.Universe, work, edition, false); var snapshot = await source.ImportAsync(f.Owner, f.Universe, edition, new(Guid.NewGuid(), "original.txt", SourceTestFixture.Bytes, SourceTestFixture.Checksum, "fixture:original", true), default); var detail = await source.InspectAsync(f.Owner, f.Universe, work, default); await source.ReviewSnapshotAsync(f.Owner, f.Universe, snapshot, new(detail.Snapshots.Single().RowVersion, "Approved"), default);
        var bytes = MediaFiles.ReferenceCard("original", []); var reference = await media.ImportAsync(f.Owner, f.Universe, MediaTestFixture.Upload(f, c, "reference", bytes) with { License = MediaTestFixture.License with { SourceSnapshotIds = [snapshot] } }, default); await MediaTestFixture.Review(s, f, reference); var derived = await media.ImportAsync(f.Owner, f.Universe, MediaTestFixture.Upload(f, c, "derived", bytes) with { ParentVersionIds = [reference.Id] }, default); await MediaTestFixture.Review(s, f, derived); var profile = await MediaTestFixture.Profile(s, f); var output = MediaTestFixture.Upload(f, c, "generation", []) with { ExpectedSha256 = "" }; var request = new GenerateMedia(Guid.NewGuid(), profile, output, "Use the original reference", [derived.Id], [], 0);
        var denied = await Assert.ThrowsAsync<RightsBlockedException>(() => media.GenerateAsync(f.Owner, f.Universe, request, default)); Assert.Contains("AiProcessingNotPermitted", denied.Message); await Assert.ThrowsAsync<RightsBlockedException>(() => media.GenerateAsync(f.Owner, f.Universe, request with { OperationId = Guid.NewGuid(), ReferenceVersionIds = [], Output = output with { License = MediaTestFixture.License with { SourceSnapshotIds = [snapshot] } } }, default)); await Assert.ThrowsAsync<RightsBlockedException>(() => media.GenerateAsync(f.Owner, f.Universe, request with { OperationId = Guid.NewGuid(), ReferenceVersionIds = [], Output = output with { ParentVersionIds = [derived.Id] } }, default)); Assert.Empty(await media.GenerationsAsync(f.Owner, f.Universe, default));
        await Permit(s, f.Owner, f.Universe, work, edition, true); var queued = await media.GenerateAsync(f.Owner, f.Universe, request, default); await Permit(s, f.Owner, f.Universe, work, edition, false); await MediaTestFixture.Drain(s); queued = (await media.GenerationsAsync(f.Owner, f.Universe, default)).Single(x => x.Id == queued.Id); Assert.Equal("Failed", queued.State); Assert.Null(queued.ExternalResourceId); Assert.Null(queued.AcceptedVersionId); Assert.Equal(0, queued.ActualCost);
        await Permit(s, f.Owner, f.Universe, work, edition, true); var unknown = await MediaTestFixture.Profile(s, f, "media.image.unknown-fixture.v1"); var submitted = await media.GenerateAsync(f.Owner, f.Universe, request with { OperationId = Guid.NewGuid(), ProfileId = unknown, Output = output with { Key = "unknown" } }, default); await MediaTestFixture.Drain(s); await Permit(s, f.Owner, f.Universe, work, edition, false); await Assert.ThrowsAsync<RightsBlockedException>(() => media.ReconcileAsync(f.Owner, f.Universe, new(Guid.NewGuid(), submitted.Id), default)); submitted = (await media.GenerationsAsync(f.Owner, f.Universe, default)).Single(x => x.Id == submitted.Id); Assert.Equal("Accepting", submitted.State); Assert.NotNull(submitted.ExternalResourceId); Assert.Null(submitted.AcceptedVersionId); Assert.Equal(0, submitted.ActualCost);
    }
    [SqlFact]
    public async Task Watch_imported_voice_cannot_be_replaced_by_colliding_generation_profile_strings()
    {
        using var root = WatchTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await WatchTestFixture.Setup(s); var media = s.GetRequiredService<IMediaLibrary>(); var profile = await media.ProfileAsync(f.Context.Owner, f.Context.Universe, new(Guid.NewGuid(), "owned-recording.v1", 1, "media.speech.tone-fixture.v1", "local:different-account", "Speech", "en-IN", f.Voice.Id.ToString("D"), 0, "INR", 0, "Fixture", "fixture:colliding-profile"), default); var g = new RegistryTestFixture.Fixture(f.Context.Owner, f.Context.Universe, f.Context.Audience, f.Context.Bible, f.Context.Episode); var gen = new GenerateMedia(Guid.NewGuid(), profile, MediaTestFixture.Upload(g, f.Character, "replacement", [], "Voice") with { ExpectedSha256 = "" }, f.Script.Current!.Body, [], [], 0); var request = WatchTestFixture.Request(f); var w = s.GetRequiredService<IWatchFactory>(); await Assert.ThrowsAsync<EvidenceBlockedException>(() => w.CreateAsync(f.Context.Owner, f.Context.Universe, request with { Scenes = [request.Scenes[0] with { VoiceVersionId = null, VoiceGeneration = gen }] }, default)); Assert.Empty(await media.GenerationsAsync(f.Context.Owner, f.Context.Universe, default));
        var job = await media.GenerateAsync(f.Context.Owner, f.Context.Universe, gen, default); await MediaTestFixture.Drain(s); job = (await media.GenerationsAsync(f.Context.Owner, f.Context.Universe, default)).Single(x => x.Id == job.Id); var replacement = (await media.AssetsAsync(f.Context.Owner, f.Context.Universe, default)).SelectMany(x => x.Versions).Single(x => x.Id == job.AcceptedVersionId); await MediaTestFixture.Review(s, g, replacement); await Assert.ThrowsAsync<EvidenceBlockedException>(() => w.CreateAsync(f.Context.Owner, f.Context.Universe, request with { Scenes = [request.Scenes[0] with { VoiceVersionId = replacement.Id }] }, default));
    }
    [SqlFact]
    public async Task Watch_generated_voice_pins_original_profile_identity_version_account_and_resource()
    {
        using var root = WatchTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await WatchTestFixture.Setup(s); var g = new RegistryTestFixture.Fixture(f.Context.Owner, f.Context.Universe, f.Context.Audience, f.Context.Bible, f.Context.Episode); var media = s.GetRequiredService<IMediaLibrary>(); var original = await MediaTestFixture.Profile(s, g, "media.speech.tone-fixture.v1", "Speech"); var profile = (await media.ProfilesAsync(f.Context.Owner, f.Context.Universe, default)).Single(x => x.Id == original); var output = MediaTestFixture.Upload(g, f.Character, "original-provider", [], "Voice") with { ExpectedSha256 = "" }; var job = await media.GenerateAsync(f.Context.Owner, f.Context.Universe, new(Guid.NewGuid(), original, output, "Hi.", [], [], 0), default); await MediaTestFixture.Drain(s); job = (await media.GenerationsAsync(f.Context.Owner, f.Context.Universe, default)).Single(x => x.Id == job.Id); var voice = (await media.AssetsAsync(f.Context.Owner, f.Context.Universe, default)).SelectMany(x => x.Versions).Single(x => x.Id == job.AcceptedVersionId); await MediaTestFixture.Review(s, g, voice); var package = await MediaTestFixture.Package(s, g, f.Character, f.Image, voice, "provider-package", profile.Configuration.Key, profile.Configuration.ResourceKey); var presentation = await media.BindPackageAsync(f.Context.Owner, f.Context.Universe, package.Id, Guid.NewGuid(), default); await RegistryTestFixture.Review(s, f.Context.Owner, f.Context.Universe, presentation);
        var editor = s.GetRequiredService<IEditorialWorkbench>(); var request = EditorialTestFixture.Request(f.Context, "provider-script"); var script = await editor.StartAsync(f.Context.Owner, f.Context.Universe, request with { Draft = request.Draft! with { Body = "Hi." } }, default); var registry = s.GetRequiredService<IUniverseRegistry>(); var episode = (await registry.EpisodesAsync(f.Context.Owner, f.Context.Universe, default)).Single(x => x.Id == f.Context.Episode); var brief = RegistryTestFixture.Brief(g) with { PinnedChoices = [new(f.Character.CharacterId, "Lead", presentation)], Budget = new(2, 0, "INR", true) }; await registry.ComposeAsync(f.Context.Owner, f.Context.Universe, new(Guid.NewGuid(), episode.RowVersion, brief, "None", [new(f.Character.CharacterId, "FictionalDialogue", "Hi.", ["curious"], [], true)], [], ContentRevisionId: script.RevisionId), default); script = await EditorialTestFixture.Approved(s, f.Context, await editor.InspectAsync(f.Context.Owner, f.Context.Universe, script.Id, default)); var w = s.GetRequiredService<IWatchFactory>(); var follow = new GenerateMedia(Guid.NewGuid(), original, output with { OperationId = Guid.NewGuid(), Key = "next-scene" }, "Hi.", [], [], 0); var create = WatchTestFixture.Request(f with { Script = script, Presentation = presentation, Voice = voice }, "same-provider") with { Aspects = ["Vertical"], Scenes = [new("scene-1", 0, 3, f.Character.CharacterId, presentation, f.Image.Id, null, "fixture:generated", VoiceGeneration: follow)] }; var changed = await media.ProfileAsync(f.Context.Owner, f.Context.Universe, profile.Configuration with { OperationId = Guid.NewGuid(), Version = 2, AccountReference = "local:changed-account" }, default); await Assert.ThrowsAsync<EvidenceBlockedException>(() => w.CreateAsync(f.Context.Owner, f.Context.Universe, create with { Scenes = [create.Scenes[0] with { VoiceGeneration = follow with { ProfileId = changed } }] }, default)); var accepted = await w.CreateAsync(f.Context.Owner, f.Context.Universe, create, default); Assert.Equal(original, accepted.Snapshot.Request.Scenes[0].VoiceGeneration!.ProfileId); await w.ControlAsync(f.Context.Owner, f.Context.Universe, accepted.Id, new(Guid.NewGuid(), accepted.RowVersion, "Cancel", "fixture:cleanup-prepared-positive-case"), default);
    }
    [SqlFact]
    public async Task Corrected_teaching_is_withheld_held_and_propagated_to_direct_bindings()
    {
        using var root = WatchTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await TrendTestFixture.Setup(s); var trends = s.GetRequiredService<ITrendWorkbench>(); var match = await TrendTestFixture.Match(s, f); var story = await TrendTestFixture.Package(s, f, match); await trends.ReviewStoryAsync(f.Owner, f.Universe, story.Id, new(Guid.NewGuid(), story.RowVersion, "Approve", "Fixture", "fixture:initial-teaching"), default); var db = s.GetRequiredService<CoreDbContext>(); var subject = await db.Subjects.Where(x => x.UniverseId == f.Universe).Select(x => x.Id).FirstAsync(); var editor = s.GetRequiredService<IEditorialWorkbench>(); var script = await editor.StartAsync(f.Owner, f.Universe, new(Guid.NewGuid(), "direct-binding", "Article", "Original synthetic story", new(Guid.NewGuid(), subject, f.ChildAudience, "en-IN", "Original story", "Verified factual context (separate from the story):\n" + TrendTestFixture.Fact + "\nOriginal fictional analogy: a learner pauses.", "Fiction", "Owned", "fixture:original"), PublicIntended: false), default); await trends.BindAsync(f.Owner, f.Universe, new(Guid.NewGuid(), story.Id, script.Id), default);
        var lesson = await s.GetRequiredService<ILessonEngine>().InspectAsync(f.Owner, f.Universe, f.ChildLesson, default); var claim = lesson.Snapshot.Bundle.Request.InterpretationClaimRevisionId; await s.GetRequiredService<IEvidenceEngine>().CorrectAsync(f.Owner, f.Universe, new(Guid.NewGuid(), claim, "Original fixture meaning needs correction", "fixture:teaching-correction"), default); var before = (await trends.StoriesAsync(f.Owner, f.Universe, default)).Single(x => x.Id == story.Id); Assert.Null(before.Snapshot); Assert.NotEmpty(before.Blocks); await Assert.ThrowsAsync<EvidenceBlockedException>(() => trends.BindAsync(f.Owner, f.Universe, new(Guid.NewGuid(), story.Id, script.Id), default)); await trends.RecheckAsync(f.Owner, f.Universe, default); var after = (await trends.StoriesAsync(f.Owner, f.Universe, default)).Single(x => x.Id == story.Id); Assert.Equal("Held", after.State); Assert.Null(after.Snapshot); var tasks = await editor.CorrectionsAsync(f.Owner, f.Universe, default); Assert.Contains(tasks, x => x.ContentId == script.ContentId); var remediation = (await trends.RemediationsAsync(f.Owner, f.Universe, default)).Single(x => x.BriefId == story.Id); var correction = await db.EditorialCorrections.AsNoTracking().SingleAsync(x => x.Id == remediation.EditorialCorrectionId); Assert.Equal(claim, correction.ClaimRevisionId); var count = tasks.Count; await trends.RecheckAsync(f.Owner, f.Universe, default); Assert.Equal(count, (await editor.CorrectionsAsync(f.Owner, f.Universe, default)).Count);
    }
